def orientations(piece, dihedral=True):
 pts=[(r,c) for r,c,v in piece]; seen={}; forms=[]
 for refl in ([False,True] if dihedral else [False]):
  for k in range(4 if dihedral else 1):
   coords=[]
   for r,c in pts:
    if refl: c=-c
    for _ in range(k): r,c=c,-r
    coords.append((r,c))
   mr=min(r for r,c in coords); mc=min(c for r,c in coords)
   norm=tuple(sorted((r-mr,c-mc) for r,c in coords))
   if norm not in seen: seen[norm]=1; forms.append(norm)
 return forms

